assert(custoRoof({0,1,2})==3 && custoRoof({1,0,2})==2);
// Oráculo independente: todas as permutações para n pequeno.
for(int n=2;n<=9;++n){
 vector<int> p(n);iota(p.begin(),p.end(),0);int otimo=INT_MAX;
 do{otimo=min(otimo,custoRoof(p));}while(next_permutation(p.begin(),p.end()));
 auto got=construirRoof(n);assert(custoRoof(got)==otimo);
 auto ordenado=got;sort(ordenado.begin(),ordenado.end());
 for(int i=0;i<n;++i)assert(ordenado[i]==i);
}
for(int n:vector<int>{10,31,32,33,65536,65537,200000}){
 auto p=construirRoof(n);auto ordenado=p;sort(ordenado.begin(),ordenado.end());
 for(int i=0;i<n;++i)assert(ordenado[i]==i);
 int referencia=1;for(int x=1;x<=n-1;++x)if((x&(x-1))==0)referencia=x;
 assert(custoRoof(p)==referencia);
}
